extern crate enum_new as enum_ordinalize;
use enum_new::Ordinalize as _;
#[derive(enum_old::Ordinalize)] #[repr(u8)] enum Old { First=1<<2, Next }
#[derive(enum_new::Ordinalize,Debug,PartialEq)] #[repr(u8)] enum New { First=1<<2, Next }
mod portable {
    pub trait OsStringExt { fn from_vec(bytes:Vec<u8>)->Self; }
    impl OsStringExt for std::ffi::OsString {
        fn from_vec(bytes:Vec<u8>)->Self { assert!(bytes.is_ascii()); String::from_utf8(bytes).unwrap().into() }
    }
}
mod ported_dirs;
fn main(){
    assert_eq!(Old::Next as u8,5);assert_eq!(Old::Next.ordinal(),8);assert!(Old::from_ordinal(5).is_none());
    println!("enum-ordinalize 3.1.15: actual=5 derived=8 from_ordinal(5)=None");
    println!("enum-ordinalize 4.4.2 / derive 4.4.2: actual={} derived={} roundtrip={:?}",New::Next as u8,New::Next.ordinal(),New::from_ordinal(5));
    assert_eq!(New::Next.ordinal(),8);assert_eq!(New::from_ordinal(5),None);
    let name=format!("{}.x","a".repeat(254));
    let old=sanitize_old::sanitize_with_options(&name,sanitize_old::Options{windows:true,truncate:true,replacement:""});
    assert_eq!(old.len(),255);assert!(old.ends_with('.'));assert!(!sanitize_old::is_sanitized_with_options(&old,sanitize_old::OptionsForCheck{windows:true,truncate:true}));
    println!("sanitize-filename 0.6.0: length=255 trailing_dot=true own_check=false");
    let new=sanitize_new::sanitize_with_options(name.clone(),sanitize_new::Options{windows:true,truncate:true,replacement:""});
    println!("sanitize-filename 0.8.0-beta: length={} trailing_dot={} own_check={}",new.len(),new.ends_with('.'),sanitize_new::is_sanitized_with_options(&new,sanitize_new::OptionsForCheck{windows:true,truncate:true}));
    assert_eq!(new.len(),255);assert!(new.ends_with('.'));
    for key in ["guards","circuit_timeouts"] {assert_eq!(sanitize_old::sanitize(key),key);}
    let mut bad=data_encoding::HEXLOWER;bad.0=vec![0xF6;514].into();
    let output=bad.encode(&[1,2,3,4]);assert!(std::str::from_utf8(output.as_bytes()).is_err());
    println!("data-encoding 2.11.1: safe public field mutation -> invalid UTF-8 String");
    let file=std::path::Path::new("target/netd-review-5/synthetic-user-dirs.dirs");
    std::fs::write(file,b"XDG_MUSIC_DIR=\"").unwrap();
    let panics=std::panic::catch_unwind(||ported_dirs::all(std::path::Path::new("/synthetic-home"),file)).is_err();assert!(panics);
    println!("dirs-sys 0.5.0: single double quote panics; exact parser + ASCII-only OsStringExt portability shim");
}

use async_executors::{LocalSpawnHandleExt, SpawnHandleExt, TimerExt};
use std::{future::pending, sync::{Arc, atomic::{AtomicBool, Ordering}}, time::Duration};

#[test]
fn local_future_keeps_rc_on_owning_thread() {
    let exec=async_executors::TokioCt::new().unwrap();
    exec.block_on(async {
        let data=std::rc::Rc::new(42);
        let h=exec.spawn_handle_local(async move { *data }).unwrap();
        assert_eq!(h.await,42);
    });
}

#[tokio::test]
async fn drop_cancels_after_first_poll() {
    struct Mark(Arc<AtomicBool>);
    impl Drop for Mark { fn drop(&mut self){self.0.store(true,Ordering::SeqCst);} }
    let flag=Arc::new(AtomicBool::new(false));
    let (started,wait)=tokio::sync::oneshot::channel();
    let mark=Mark(flag.clone());
    let exec=async_executors::TokioCt::try_current().unwrap();
    let h=exec.spawn_handle(async move {let _mark=mark;started.send(()).unwrap();pending::<()>().await;}).unwrap();
    wait.await.unwrap();drop(h);
    tokio::time::timeout(Duration::from_secs(2),async {while !flag.load(Ordering::SeqCst){tokio::task::yield_now().await;}}).await.unwrap();
}

#[tokio::test]
async fn detach_preserves_task_and_output() {
    let (send,receive)=tokio::sync::oneshot::channel();
    let (finished,done)=tokio::sync::oneshot::channel();
    let exec=async_executors::TokioCt::try_current().unwrap();
    exec.spawn_handle(async move {finished.send(receive.await.unwrap()).unwrap();}).unwrap().detach();
    send.send(17).unwrap();
    assert_eq!(tokio::time::timeout(Duration::from_secs(2),done).await.unwrap().unwrap(),17);
}

#[test]
fn timeout_reports_expiry_and_ready_value() {
    let exec=async_executors::TokioTp::new().unwrap();
    exec.block_on(async {
        assert_eq!(exec.timeout(Duration::from_secs(1),async {42}).await.unwrap(),42);
        assert!(exec.timeout(Duration::from_millis(1),pending::<()>()).await.is_err());
    });
}

